# =====================================================================
#  it.map - phishing phrases for IT companies, SaaS and hosting
#  Part of: phishing-detector by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake domain expiry / "domain listing" scams, SSL certificate
#           expiry, hosting / cPanel / Plesk suspension and failed
#           payments, Microsoft 365 / Google Workspace admin alerts,
#           cloud billing (AWS, Azure, GCP, Cloudflare), GitHub / GitLab
#           security alerts, MFA / VPN re-enrollment, software license
#           renewals, fake helpdesk tickets
#
#  Avoided: real monitoring alerts, deployment notices, "ticket updated",
#           plain renewal reminders, because IT teams get real ones daily.
# =====================================================================

# ===== English =====
# Domains
/(your\s+)?domain\s+(name\s+)?(will\s+expire|has\s+expired|expiration\s+notice|is\s+about\s+to\s+expire)[^.]{0,40}(renew|click|immediately|today|within)/i
/(final|urgent|last)\s+(notice|reminder)\s*:?\s+(domain|dns)\s+(expir|renew|suspen)/i
/domain\s+(listing|registration)\s+(service|submission)\s+(notice|expiration|invoice)/i
/(seo|search\s+engine)\s+(submission|registration)\s+(for|of)\s+(your\s+)?domain/i
/(dns|nameserver)\s+(records?\s+)?(will\s+be\s+|has\s+been\s+)?(suspended|deleted|disabled)\s+(unless|due\s+to|within)/i
# SSL
/(your\s+)?ssl\s+(\/\s*tls\s+)?certificate\s+(has\s+expired|will\s+expire|expires\s+today)[^.]{0,40}(renew|click|install|verify)/i
# Hosting
/(your\s+)?(hosting|cpanel|plesk|server|vps|website)\s+(account\s+)?(has\s+been|will\s+be|is)\s+(suspended|deactivated|terminated|disabled)\s+(due\s+to|unless|for|within)/i
/(hosting|server|domain)\s+(payment|renewal|invoice)\s+(has\s+)?(failed|declined|is\s+overdue|unpaid)/i
/(storage|disk|bandwidth)\s+(quota|limit)\s+(exceeded|reached)\s+(on\s+)?(your\s+)?(server|hosting|account)[^.]{0,30}(upgrade|click)/i
# Microsoft 365 / Google Workspace
/(microsoft\s+365|office\s+365|o365|outlook|exchange\s+online|google\s+workspace|g\s+suite)\s+(license|subscription|account|mailbox)\s+(has\s+)?(expired|will\s+expire|suspended|deactivated|payment\s+failed)/i
/(admin|administrator)\s+(action|attention)\s+required[^.]{0,40}(tenant|license|subscription|workspace|domain)/i
/(sharepoint|onedrive|teams)\s+(document|file|message)\s+(shared|received|pending)[^.]{0,30}(view|open|access)/i
# Cloud billing
/(aws|amazon\s+web\s+services|azure|google\s+cloud|gcp|cloudflare|digitalocean|hetzner|ovh)\s+(account|billing|subscription|services?)\s+(suspended|suspension|payment\s+failed|past\s+due|will\s+be\s+(terminated|suspended))/i
/(update|verify)\s+your\s+(billing|payment)\s+(method|information|details)\s+to\s+avoid\s+(service\s+)?(interruption|suspension|termination)/i
# Dev platforms
/(github|gitlab|bitbucket|npm|docker\s+hub)\s+(security\s+alert|account\s+(suspended|flagged|locked)|unusual\s+activity|repository\s+(flagged|suspended))/i
/(oauth|third-?party)\s+app(lication)?\s+(authorization|access)\s+(request|required)\s+(for|to)\s+your\s+(account|repository|organization)/i
# MFA / VPN
/(re-?register|re-?enroll|reset|update)\s+your\s+(mfa|2fa|two-?factor|authenticator|vpn)\s+(device|app|settings|access|token)/i
/(mfa|2fa|two-?factor)\s+(will\s+be|has\s+been)\s+(disabled|reset|turned\s+off)\s+(unless|within|today)/i
/(vpn|remote\s+access)\s+(certificate|profile|account)\s+(has\s+)?(expired|will\s+expire|must\s+be\s+updated)/i
# Licenses / helpdesk
/(adobe|autodesk|jetbrains|vmware|veeam|kaspersky|eset|norton|mcafee)\s+(license|subscription)\s+(has\s+)?(expired|will\s+expire|renewal\s+failed|payment\s+failed)/i
/(it\s+)?(help\s?desk|service\s?desk|support)\s+ticket\s+#?\S+\s+(requires|awaiting)\s+(your\s+)?(verification|login|confirmation|action)/i

# ===== Spanish =====
/su\s+dominio\s+(caduca|expira|ha\s+caducado|ha\s+expirado)[^.]{0,40}(renueve|haga\s+clic|inmediatamente)/iu
/su\s+certificado\s+ssl\s+(ha\s+caducado|caduca|expira)/iu
/su\s+(cuenta\s+de\s+)?(hosting|alojamiento|servidor)\s+(ha\s+sido|ser[áa])\s+(suspendid[oa]|desactivad[oa])/iu
/(licencia|suscripci[óo]n)\s+de\s+(microsoft\s+365|office\s+365|google\s+workspace)\s+(ha\s+caducado|caducar[áa]|suspendida)/iu

# ===== German =====
/ihre\s+domain\s+(l[äa]uft\s+ab|ist\s+abgelaufen)[^.]{0,40}(verl[äa]ngern|klicken|sofort)/iu
/ihr\s+ssl-?zertifikat\s+(l[äa]uft\s+ab|ist\s+abgelaufen)/iu
/ihr\s+(hosting|server|webspace)(-?konto)?\s+(wird|wurde)\s+(gesperrt|deaktiviert|gek[üu]ndigt)/iu
/(microsoft\s+365|office\s+365|google\s+workspace)[- ](lizenz|abonnement)\s+(abgelaufen|l[äa]uft\s+ab|gesperrt)/iu

# ===== French =====
